package run.ikaros.password; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Mono; import run.ikaros.common.NotFoundException; @Service public class SecretReferenceService{private final PasswordVaultItemRepository items;public SecretReferenceService(PasswordVaultItemRepository i){items=i;}public Mono<SecretReferenceView> reference(UUID a,UUID id){return items.findById(id).filter(x->x.ownerId().equals(a)&&!x.tombstone()).switchIfEmpty(Mono.error(new NotFoundException("Vault Item 不存在或无权访问"))).map(x->new SecretReferenceView(x.id(),x.vaultId(),"secret://password/vault/item/"+x.id()));}}
